-- Тема 6: Регулируемые перекрёстки — топик id=6, категория id=5
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(5,6,'Разрешён ли поворот налево на регулируемом перекрёстке при зелёном сигнале светофора, если по этой полосе также движется встречный трамвай прямо?',
'["Да, но водитель обязан уступить дорогу трамваю и встречным ТС, движущимся прямо","Нет, поворот запрещён в любом случае","Да, без ограничений","Только если нет других ТС на дороге"]'::jsonb,0,
'При повороте налево или развороте по зелёному сигналу водитель обязан уступить дорогу трамваю попутного направления и ТС, движущимся со встречного направления прямо или направо.',1),
(5,6,'Как должен действовать водитель при повороте направо на регулируемом перекрёстке?',
'["Уступить дорогу пешеходам, переходящим проезжую часть, на которую он поворачивает","Пешеходы обязаны пропустить поворачивающий автомобиль","Остановиться перед перекрёстком в любом случае","Подать звуковой сигнал пешеходам"]'::jsonb,0,
'При повороте направо водитель обязан уступить дорогу пешеходам и велосипедистам, пересекающим проезжую часть дороги, на которую он поворачивает.',2),
(5,6,'Что должен делать водитель трамвая на регулируемом перекрёстке, если сигнал светофора разрешает движение, но путь загорожен другими ТС?',
'["Трамвай имеет право проезда независимо от загруженности, но должен избегать столкновения","Трамвай обязан всегда уступать всем ТС","Трамвай не имеет права двигаться первым","Правило зависит только от разметки"]'::jsonb,0,
'При разрешающем сигнале трамвай движется с учётом его приоритета, но обязан избегать создания опасности для других участников движения.',3),
(5,6,'Как действовать водителю на регулируемом перекрёстке при включении дополнительной секции светофора с красной стрелкой (запрещающей) при основном зелёном?',
'["Движение в направлении красной стрелки запрещено, в остальных разрешённых направлениях — можно двигаться","Движение полностью запрещено","Все направления разрешены","Означает неисправность светофора"]'::jsonb,0,
'Выключенная или включённая красная дополнительная секция запрещает движение только в направлении данной секции; в остальных направлениях действует основной сигнал.',4),
(5,6,'Можно ли проехать регулируемый перекрёсток на зелёный сигнал, если на пути движется скорая помощь с включёнными спецсигналами?',
'["Нет, необходимо уступить дорогу ТС со спецсигналами независимо от сигнала светофора","Да, преимущество только на нерегулируемых перекрёстках","Да, если скорая едет по другой полосе","Нет, только если едет пожарная машина"]'::jsonb,0,
'Водители обязаны уступить дорогу ТС с включёнными синим проблесковым маячком и спецсигналом независимо от сигнала светофора.',5),
(5,6,'В каком случае водитель обязан остановиться перед стоп-линией на регулируемом перекрёстке?',
'["При запрещающем сигнале светофора или регулировщика","Только по требованию другого водителя","Только при заторе на перекрёстке","Стоп-линия не имеет обязательной силы"]'::jsonb,0,
'При запрещающем сигнале светофора или регулировщика водитель обязан остановиться перед стоп-линией, а при её отсутствии — перед пересекаемой проезжей частью.',6);

-- Тема 7: Нерегулируемые перекрёстки — топик id=7, категория id=5
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(5,7,'Кто имеет преимущество на нерегулируемом перекрёстке неравнозначных дорог?',
'["Водитель, движущийся по главной дороге","Водитель, движущийся справа","Водитель, движущийся быстрее","Преимущество всегда у трамвая"]'::jsonb,0,
'На перекрёстке неравнозначных дорог водитель ТС, движущегося по второстепенной дороге, обязан уступить дорогу ТС, приближающимся по главной, независимо от направления их движения.',1),
(5,7,'Как должен поступить водитель трамвая на нерегулируемом перекрёстке равнозначных дорог?',
'["Трамвай имеет преимущество перед безрельсовыми ТС независимо от направления движения","Трамвай всегда должен уступать дорогу","Преимущество определяется по правилу правой руки, как для обычных ТС","Трамвай обязан останавливаться перед любым перекрёстком"]'::jsonb,0,
'На нерегулируемых перекрёстках равнозначных дорог трамвай имеет преимущество перед безрельсовыми транспортными средствами независимо от направления его дальнейшего движения.',2),
(5,7,'Что означает знак "Уступите дорогу" на нерегулируемом перекрёстке?',
'["Водитель обязан уступить дорогу ТС, движущимся по пересекаемой дороге","Перекрёсток закрыт для проезда","Требуется полная остановка независимо от обстановки","Знак действует только для грузовых ТС"]'::jsonb,0,
'Знак 2.4 "Уступите дорогу" обязывает водителя уступить дорогу транспортным средствам, движущимся по пересекаемой (главной) дороге.',3),
(5,7,'Что означает знак "Движение без остановки запрещено"?',
'["Водитель обязан остановиться перед перекрёстком и только после этого продолжить движение, убедившись в безопасности","Требуется снизить скорость без полной остановки","Знак действует только ночью","Означает конец главной дороги"]'::jsonb,0,
'Знак 2.5 обязывает водителя остановиться перед стоп-линией, а при её отсутствии — перед краем пересекаемой проезжей части, и только после этого продолжить движение, убедившись в безопасности.',4),
(5,7,'На равнозначном перекрёстке трамвай и автомобиль подъезжают одновременно, автомобиль справа от трамвая. Кто имеет преимущество?',
'["Трамвай, так как рельсовый транспорт имеет приоритет независимо от направления его движения","Автомобиль, так как он справа","Тот, кто первым въехал на перекрёсток","Оба должны уступить друг другу"]'::jsonb,0,
'На нерегулируемых равнозначных перекрёстках трамвай имеет преимущество перед безрельсовыми ТС независимо от направления его движения.',5),
(5,7,'В каком случае на нерегулируемом перекрёстке равнозначных дорог водитель должен руководствоваться правилом "помеха справа"?',
'["Если оба ТС движутся по дорогам без покрытия или по одной из них, при отсутствии знаков приоритета","Всегда, независимо от типа покрытия","Только на дорогах с твёрдым покрытием","Правило применяется только к пешеходам"]'::jsonb,0,
'При отсутствии знаков приоритета на равнозначном перекрёстке водитель обязан уступить дорогу ТС, приближающимся справа.',6),
(5,7,'Как определяется главная дорога при пересечении дороги с покрытием и грунтовой дороги, если знаки приоритета отсутствуют?',
'["Дорога с покрытием считается главной по отношению к грунтовой","Грунтовая дорога считается главной","Главная дорога не определена, действует правило помехи справа","Обе дороги считаются равнозначными"]'::jsonb,0,
'При отсутствии знаков приоритета дорога с покрытием (асфальт, бетон и т.п.) считается главной по отношению к грунтовой дороге.',7);
